\Музыка(
	[
		Дорожка([1 2 3 5 3 2 1 ø] инструмент: Инструмент.флейта)
		Дорожка(
			[{1𝅝 3 5} {5𝅝 7 9}]
			инструмент: Инструмент.пианино
			громкость: 50%
		)
	]
)\

\ячейка: [1 3 5 3]
Музыка(
	Дорожка(
		ячейка
		.соСписком(
			ячейка.преобразовать(ƒ(n2•#) n2 + 2)
		)
		.соСписком(
			ячейка.перевёрнутый()
		)
		.соСписком(
			ячейка.преобразовать(ƒ(n3•#) 8 - n3)
		)
		инструмент: Инструмент.пианино
	)
)\

\Подмостки(
	[Фраза('🕵 сыщик ждал')]
	эффекты: [
		Цветокоррекция(насыщенность: 0% контраст: 150%)
	]
)\

\Фраза(
	'привет'
	покой: Последовательность(
		{0%: Поза(поворот: 360°) 100%: Поза(поворот: 0°)}
	)\🪲

\Фраза(
	'🐈'
	исчезновение: Последовательность.исчезновение(
		длительность: 1s
	)
)\
